statement:
What does this code print (Node.js 22, run as a script with node main.js)?

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function main() {
  const out = [];
  [30, 10, 20].forEach(async (ms) => {
    await sleep(ms);
    out.push(ms);
  });
  console.log(out.join(",") || "(empty)");
  await sleep(100);
  console.log(out.join(","));
}
main();
